// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// One approval request, in the caller's projection
	// (GET /approvals/{requestId})
	GetApproval(ctx context.Context, request GetApprovalRequestObject) (GetApprovalResponseObject, error)
	// Authorise an approved withdrawal to execute (the hold), on the authoriser's own PIN step-up
	// (POST /approvals/{requestId}/holds)
	AuthorisePayout(ctx context.Context, request AuthorisePayoutRequestObject) (AuthorisePayoutResponseObject, error)
	// Reject a request with one of the four reasons, resting on the rejecter's own PIN step-up
	// (POST /approvals/{requestId}/rejections)
	RejectApproval(ctx context.Context, request RejectApprovalRequestObject) (RejectApprovalResponseObject, error)
	// Sign a request, resting on the signer's own PIN step-up
	// (POST /approvals/{requestId}/signatures)
	SignApproval(ctx context.Context, request SignApprovalRequestObject) (SignApprovalResponseObject, error)
	// Complete a new-device sign-in with the code sent to the registered phone (public)
	// (POST /auth/codes/verify)
	PostVerifyCode(ctx context.Context, request PostVerifyCodeRequestObject) (PostVerifyCodeResponseObject, error)
	// Trust a first device with an enrolment code, and sign in on it (public)
	// (POST /auth/enrol)
	PostEnrol(ctx context.Context, request PostEnrolRequestObject) (PostEnrolResponseObject, error)
	// The PIN step-up — a proof that authorises ONE act of ONE kind (0005)
	// (POST /auth/pin-proofs)
	PostPinProof(ctx context.Context, request PostPinProofRequestObject) (PostPinProofResponseObject, error)
	// Sign in with the one credential box and a PIN (public)
	// (POST /auth/sign-in)
	PostSignIn(ctx context.Context, request PostSignInRequestObject) (PostSignInResponseObject, error)
	// End this session
	// (POST /auth/sign-out)
	PostSignOut(ctx context.Context, request PostSignOutRequestObject) (PostSignOutResponseObject, error)
	// Liveness and database reachability
	// (GET /healthz)
	GetHealthz(ctx context.Context, request GetHealthzRequestObject) (GetHealthzResponseObject, error)
	// Release a hold whose transfer definitively failed, saying why
	// (POST /holds/{holdId}/releases)
	ReleaseHold(ctx context.Context, request ReleaseHoldRequestObject) (ReleaseHoldResponseObject, error)
	// One loan's position as at a value date
	// (GET /loans/{loanId})
	GetLoan(ctx context.Context, request GetLoanRequestObject) (GetLoanResponseObject, error)
	// Who the caller is - their own member records and current posts
	// (GET /me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)
	// A member's loans as at a value date (the member, or an officer of their society)
	// (GET /members/{memberId}/loans)
	GetMemberLoans(ctx context.Context, request GetMemberLoansRequestObject) (GetMemberLoansResponseObject, error)
	// A member's savings statement — one record, two projections
	// (GET /members/{memberId}/statement)
	GetMemberStatement(ctx context.Context, request GetMemberStatementRequestObject) (GetMemberStatementResponseObject, error)
	// A member's savings, what they may withdraw now, and what was deducted and why
	// (GET /members/{memberId}/withdrawable)
	GetMemberWithdrawable(ctx context.Context, request GetMemberWithdrawableRequestObject) (GetMemberWithdrawableResponseObject, error)
	// What a withdrawal of an amount would cost today (indicative)
	// (GET /members/{memberId}/withdrawal-quote)
	GetWithdrawalQuote(ctx context.Context, request GetWithdrawalQuoteRequestObject) (GetWithdrawalQuoteResponseObject, error)
	// A member's own withdrawal requests, newest first, in the member projection
	// (GET /members/{memberId}/withdrawal-requests)
	GetMemberWithdrawalRequests(ctx context.Context, request GetMemberWithdrawalRequestsRequestObject) (GetMemberWithdrawalRequestsResponseObject, error)
	// The society's chart of accounts
	// (GET /societies/{societyId}/accounts)
	GetChartOfAccounts(ctx context.Context, request GetChartOfAccountsRequestObject) (GetChartOfAccountsResponseObject, error)
	// One account's entries with a running balance
	// (GET /societies/{societyId}/accounts/{accountCode}/ledger)
	GetGeneralLedger(ctx context.Context, request GetGeneralLedgerRequestObject) (GetGeneralLedgerResponseObject, error)
	// The society's approval requests, newest first, in the officer projection
	// (GET /societies/{societyId}/approval-requests)
	GetSocietyApprovalRequests(ctx context.Context, request GetSocietyApprovalRequestsRequestObject) (GetSocietyApprovalRequestsResponseObject, error)
	// Record a contribution that arrived, on the recorder's own PIN step-up
	// (POST /societies/{societyId}/contributions)
	RecordContribution(ctx context.Context, request RecordContributionRequestObject) (RecordContributionResponseObject, error)
	// Entries with every line, filtered by reference, member, actor and value date
	// (GET /societies/{societyId}/journal)
	GetJournal(ctx context.Context, request GetJournalRequestObject) (GetJournalResponseObject, error)
	// postAll — commit a whole import in ONE transaction (LEDGER_CONTRACT §1)
	// (POST /societies/{societyId}/ledger/batches)
	PostLedgerBatch(ctx context.Context, request PostLedgerBatchRequestObject) (PostLedgerBatchResponseObject, error)
	// The society's loan book as at a value date (officers only)
	// (GET /societies/{societyId}/loans)
	GetSocietyLoans(ctx context.Context, request GetSocietyLoansRequestObject) (GetSocietyLoansResponseObject, error)
	// A member's enrolment codes, for an officer of the society — who issued each, when, and the device it trusted
	// (GET /societies/{societyId}/members/{memberId}/enrolment-codes)
	GetEnrolmentCodes(ctx context.Context, request GetEnrolmentCodesRequestObject) (GetEnrolmentCodesResponseObject, error)
	// An officer issues a member's enrolment code, on their own step-up; a signatory's comes in two halves
	// (POST /societies/{societyId}/members/{memberId}/enrolment-codes)
	IssueEnrolmentCode(ctx context.Context, request IssueEnrolmentCodeRequestObject) (IssueEnrolmentCodeResponseObject, error)
	// An officer releases a member who is locked out of signing in, in person, saying why
	// (POST /societies/{societyId}/members/{memberId}/lock-releases)
	ReleaseLock(ctx context.Context, request ReleaseLockRequestObject) (ReleaseLockResponseObject, error)
	// Record a payout that happened, on the recorder's own PIN step-up
	// (POST /societies/{societyId}/payouts)
	RecordPayout(ctx context.Context, request RecordPayoutRequestObject) (RecordPayoutResponseObject, error)
	// Every account's debits, credits and balance as at a date
	// (GET /societies/{societyId}/trial-balance)
	GetTrialBalance(ctx context.Context, request GetTrialBalanceRequestObject) (GetTrialBalanceResponseObject, error)
	// Raise a withdrawal request, on the raiser's own PIN step-up
	// (POST /societies/{societyId}/withdrawal-requests)
	RaiseWithdrawalRequest(ctx context.Context, request RaiseWithdrawalRequestRequestObject) (RaiseWithdrawalRequestResponseObject, error)
}

type StrictHandlerFunc = strictnethttp.StrictHTTPHandlerFunc
type StrictMiddlewareFunc = strictnethttp.StrictHTTPMiddlewareFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

// GetApproval operation middleware
func (sh *strictHandler) GetApproval(w http.ResponseWriter, r *http.Request, requestId openapi_types.UUID) {
	var request GetApprovalRequestObject

	request.RequestId = requestId

	handler := func(ctx context.Context, w http.ResponseWriter, r *http.Request, request interface{}) (interface{}, error) {
		return sh.ssi.GetApproval(ctx, request.(GetApprovalRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "GetApproval")
	}

	response, err := handler(r.Context(), w, r, request)

	if err != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, err)
	} else if validResponse, ok := response.(GetApprovalResponseObject); ok {
		if err := validResponse.VisitGetApprovalResponse(w); err != nil {
			sh.options.ResponseErrorHandlerFunc(w, r, err)
		}
	} else if response != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, fmt.Errorf("unexpected response type: %T", response))
	}
}

